import sys
import heapq
from collections import defaultdict

def dijkstra(graph, start, k, types):
    pq = [(0, {types[start]}, start)]
    visited = set()
    while pq:
        crowd_value, seen_types, node = heapq.heappop(pq)
        if len(seen_types) >= k:
            return crowd_value
        if node in visited:
            continue
        visited.add(node)
        for neighbor, cost in graph[node]:
            if neighbor not in visited:
                new_types = seen_types | {types[neighbor]}
                heapq.heappush(pq, (max(crowd_value, cost), new_types, neighbor))
    return -1

def main():
    import sys
    input = sys.stdin.read().split()
    idx = 0
    n = int(input[idx])
    m = int(input[idx + 1])
    q = int(input[idx + 2])
    idx += 3
    types = [int(x) for x in input[idx:idx + n]]
    idx += n
    graph = defaultdict(list)
    for _ in range(m):
        x = int(input[idx]) - 1
        y = int(input[idx + 1]) - 1
        u = int(input[idx + 2])
        idx += 3
        graph[x].append((y, u))
        graph[y].append((x, u))
    results = []
    for _ in range(q):
        x = int(input[idx]) - 1
        y =int(input[idx + 1]) - 1
        k = int(input[idx + 2])
        idx += 3
        if x == y:
            if k <= 1:
                results.append(0)
            else:
                results.append(-1)
        else:
            results.append(dijkstra(graph, x, k, types))
    for result in results:
        print(result)

if __name__ == "__main__":
    main()
